-- ==========================================================
-- Learning Hub - Answer-key reconciliation
--
-- Rewrites the `data` payload of every activity block to match the
-- official "Final References and Key to Correction" document:
--   * corrected answer keys where the seeded answer disagreed with it;
--   * the target word actually marked __underlined__ in the prompts that
--     refer to "the underlined word";
--   * `"subjective": true` on every question the key records as
--     "Answers may vary", with the key's model answer kept in
--     `sampleAnswer` for the teacher's review screen.
--
-- This UPDATEs blocks in place, matched on module title + block title, so
-- student progress, highlights and assignments all survive — unlike
-- re-running the seed files, which drop and re-insert the modules.
--
-- Safe to re-run. Run AFTER the seed_content_*.sql files and
-- add_subjective_review.sql.
-- ==========================================================

update module_content mc
set data = '{"instructions": "Directions: For each everyday vocabulary word below, select its correct meaning from the dropdown.", "questions": [{"id": "q1", "type": "matching", "prompt": "Match each term to its meaning.", "points": 5, "pairs": [{"left": "Jeepney", "right": "Public transport commonly used in the Philippines"}, {"left": "Registrar''s Office", "right": "University office that manages student records"}, {"left": "Tuition", "right": "Payment for education"}, {"left": "Sari-sari Store", "right": "Small neighborhood store"}, {"left": "Barangay Clearance", "right": "Required document from your local government unit"}]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 1: Everyday Vocabulary – Match the Term';

update module_content mc
set data = '{"instructions": "Directions: Interactive text: \"During my first week at the university, I reviewed the syllabus for each subject, attended my first lecture, and visited the campus library. I also asked about internship opportunities and checked the deadline for dropping courses.\"\n\nFor each academic term below, select its correct definition from the dropdown.", "questions": [{"id": "q1", "type": "matching", "prompt": "Match each academic term to its definition.", "points": 5, "pairs": [{"left": "Syllabus", "right": "A summary outline of topics and activities in a course"}, {"left": "Lecture", "right": "A formal educational talk given by a professor"}, {"left": "Deadline", "right": "The latest time by which something should be submitted"}, {"left": "Internship", "right": "Practical work experience in a field of study"}, {"left": "Campus", "right": "The grounds and buildings of a university"}]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 2: Academic Vocabulary – Match the Term';

update module_content mc
set data = '{"instructions": "Directions: Write an original sentence using each word below. Make sure each sentence reflects a real-life academic or school-related situation. Example — Classroom: \"The classroom was prepared for our group presentation.\"", "questions": [{"id": "q1", "type": "short_answer", "subjective": true, "prompt": "Write a sentence using: __portal__", "points": 1, "sampleAnswer": "The portal lets me view my grades and assignments."}, {"id": "q2", "type": "short_answer", "subjective": true, "prompt": "Write a sentence using: __modules__", "points": 1, "sampleAnswer": "We were given multiple modules for asynchronous learning."}, {"id": "q3", "type": "short_answer", "subjective": true, "prompt": "Write a sentence using: __enrollment__", "points": 1, "sampleAnswer": "I completed my enrollment online with minimal help."}, {"id": "q4", "type": "short_answer", "subjective": true, "prompt": "Write a sentence using: __thesis__", "points": 1, "sampleAnswer": "My thesis proposal was approved after revision."}, {"id": "q5", "type": "short_answer", "subjective": true, "prompt": "Write a sentence using: __dean''s office__", "points": 1, "sampleAnswer": "I went to the Dean''s Office to ask about overload forms."}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 3: Academic Vocabulary in Action';

update module_content mc
set data = '{"instructions": "Directions: Choose the most suitable synonym to replace the __underlined__ word in each sentence.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "The professor held a __webinar__ on mental health awareness.", "points": 1, "options": ["online lecture", "meeting"], "correctIndex": 0}, {"id": "q2", "type": "multiple_choice", "prompt": "I received __feedback__ on my performance.", "points": 1, "options": ["criticism", "response"], "correctIndex": 1}, {"id": "q3", "type": "multiple_choice", "prompt": "The school''s __repository__ stores all thesis submissions.", "points": 1, "options": ["archive", "drive"], "correctIndex": 0}, {"id": "q4", "type": "multiple_choice", "prompt": "My __assessment__ was based on quizzes and participation.", "points": 1, "options": ["test", "review"], "correctIndex": 0}, {"id": "q5", "type": "multiple_choice", "prompt": "I had a heavy __course load__ this semester.", "points": 1, "options": ["schedule", "number of subjects"], "correctIndex": 1}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 4: Vocabulary Connections – Choosing the Right Synonym';

update module_content mc
set data = '{"instructions": "Directions: Complete the conversation using the most appropriate vocabulary from the box: Advisor, Cafeteria, Lecture, Scholarship, Classroom, Library.\n\nAna: \"Hey, have you submitted your ___ form?\"\nLance: \"Yes, I brought it to the ___ yesterday.\"\nAna: \"Same! I also stopped by the ___ to get lunch before heading to the ___ to return a book.\"\nLance: \"Cool! Let''s talk later after our ___ with the professor.\"", "questions": [{"id": "q1", "type": "short_answer", "prompt": "Blank (1): \"...submitted your ___ form?\"", "points": 1, "acceptedAnswers": ["Scholarship"]}, {"id": "q2", "type": "short_answer", "prompt": "Blank (2): \"I brought it to the ___ yesterday.\"", "points": 1, "acceptedAnswers": ["Advisor", "Advisor''s Office"]}, {"id": "q3", "type": "short_answer", "prompt": "Blank (3): \"...stopped by the ___ to get lunch...\"", "points": 1, "acceptedAnswers": ["Cafeteria"]}, {"id": "q4", "type": "short_answer", "prompt": "Blank (4): \"...heading to the ___ to return a book.\"", "points": 1, "acceptedAnswers": ["Library"]}, {"id": "q5", "type": "short_answer", "prompt": "Blank (5): \"...after our ___ with the professor.\"", "points": 1, "acceptedAnswers": ["Lecture"]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 5: Contextual Dialogue Completion';

update module_content mc
set data = '{"instructions": "Directions: Add the appropriate prefix or suffix to each root word. You may write just the affix (for example, __-ment__) or the complete word (__management__).", "questions": [{"id": "q1", "type": "short_answer", "prompt": "manage → ____", "points": 1, "acceptedAnswers": ["-ment", "ment", "management"]}, {"id": "q2", "type": "short_answer", "prompt": "enroll → ____", "points": 1, "acceptedAnswers": ["re-", "re", "re-enroll", "reenroll"]}, {"id": "q3", "type": "short_answer", "prompt": "prepare → ____", "points": 1, "acceptedAnswers": ["un-", "un", "unprepared"]}, {"id": "q4", "type": "short_answer", "prompt": "educate → ____", "points": 1, "acceptedAnswers": ["-tion", "tion", "education"]}, {"id": "q5", "type": "short_answer", "prompt": "organize → ____", "points": 1, "acceptedAnswers": ["-er", "er", "organizer"]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 1: Word Formation Drill';

update module_content mc
set data = '{"instructions": "Directions: Identify and correct the morphological error in each sentence.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "The team was very disorganizated.", "points": 1, "acceptedAnswers": ["disorganized"]}, {"id": "q2", "type": "short_answer", "prompt": "Please submital the form before the deadline.", "points": 1, "acceptedAnswers": ["submit"]}, {"id": "q3", "type": "short_answer", "prompt": "They are unconfidence in speaking.", "points": 1, "acceptedAnswers": ["unconfident"]}, {"id": "q4", "type": "short_answer", "prompt": "We will preparize the documents by tomorrow.", "points": 1, "acceptedAnswers": ["prepare"]}, {"id": "q5", "type": "short_answer", "prompt": "I was misunderstook by the teacher.", "points": 1, "acceptedAnswers": ["misunderstood"]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 2: Error Identification and Correction';

update module_content mc
set data = '{"instructions": "Directions: Complete the chart with related forms for each root word (noun, verb, and adjective form).", "questions": [{"id": "q1n", "type": "short_answer", "prompt": "Act — Noun form", "points": 1, "acceptedAnswers": ["action"]}, {"id": "q1v", "type": "short_answer", "prompt": "Act — Verb form", "points": 1, "acceptedAnswers": ["act"]}, {"id": "q1a", "type": "short_answer", "prompt": "Act — Adjective form", "points": 1, "acceptedAnswers": ["active"]}, {"id": "q2n", "type": "short_answer", "prompt": "Decide — Noun form", "points": 1, "acceptedAnswers": ["decision"]}, {"id": "q2v", "type": "short_answer", "prompt": "Decide — Verb form", "points": 1, "acceptedAnswers": ["decide"]}, {"id": "q2a", "type": "short_answer", "prompt": "Decide — Adjective form", "points": 1, "acceptedAnswers": ["decisive"]}, {"id": "q3n", "type": "short_answer", "prompt": "Organize — Noun form", "points": 1, "acceptedAnswers": ["organization"]}, {"id": "q3v", "type": "short_answer", "prompt": "Organize — Verb form", "points": 1, "acceptedAnswers": ["organize"]}, {"id": "q3a", "type": "short_answer", "prompt": "Organize — Adjective form", "points": 1, "acceptedAnswers": ["organized"]}, {"id": "q4n", "type": "short_answer", "prompt": "Succeed — Noun form", "points": 1, "acceptedAnswers": ["success"]}, {"id": "q4v", "type": "short_answer", "prompt": "Succeed — Verb form", "points": 1, "acceptedAnswers": ["succeed"]}, {"id": "q4a", "type": "short_answer", "prompt": "Succeed — Adjective form", "points": 1, "acceptedAnswers": ["successful"]}, {"id": "q5n", "type": "short_answer", "prompt": "Apply — Noun form", "points": 1, "acceptedAnswers": ["application"]}, {"id": "q5v", "type": "short_answer", "prompt": "Apply — Verb form", "points": 1, "acceptedAnswers": ["apply"]}, {"id": "q5a", "type": "short_answer", "prompt": "Apply — Adjective form", "points": 1, "acceptedAnswers": ["applicable"]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 3: Word Family Table';

update module_content mc
set data = '{"instructions": "Directions: Rearrange the words to form grammatically correct sentences.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "Unscramble: submitted / the / already / group / has / report / our", "points": 1, "acceptedAnswers": ["Our group has already submitted the report."]}, {"id": "q2", "type": "short_answer", "prompt": "Unscramble: class / was / the / by / joined / late / student / a", "points": 1, "acceptedAnswers": ["A student joined the class late.", "The class was joined by a late student."]}, {"id": "q3", "type": "short_answer", "prompt": "Unscramble: assignments / checking / is / now / professor / the / our", "points": 1, "acceptedAnswers": ["Our professor is checking the assignments now.", "Our professor is now checking assignments."]}, {"id": "q4", "type": "short_answer", "prompt": "Unscramble: day / it / tiring / very / a / was", "points": 1, "acceptedAnswers": ["It was a very tiring day."]}, {"id": "q5", "type": "short_answer", "prompt": "Unscramble: quiet / library / in / the / be / should / we", "points": 1, "acceptedAnswers": ["We should be quiet in the library."]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 1: Sentence Unscrambling';

update module_content mc
set data = '{"instructions": "Directions: Combine the two sentences into one using an appropriate connector.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "Combine: \"She was tired.\" + \"She finished the work.\"", "points": 1, "acceptedAnswers": ["Although she was tired, she finished the work.", "She was tired, but she finished the work."]}, {"id": "q2", "type": "short_answer", "prompt": "Combine: \"The class started.\" + \"He was still outside.\"", "points": 1, "acceptedAnswers": ["When the class started, he was still outside.", "The class started, but he was still outside."]}, {"id": "q3", "type": "short_answer", "prompt": "Combine: \"I studied hard.\" + \"I passed the exam.\"", "points": 1, "acceptedAnswers": ["Because I studied hard, I passed the exam.", "I studied hard, so I passed the exam."]}, {"id": "q4", "type": "short_answer", "prompt": "Combine: \"It rained.\" + \"We played indoors.\"", "points": 1, "acceptedAnswers": ["Since it rained, we played indoors.", "It rained, so we played indoors."]}, {"id": "q5", "type": "short_answer", "prompt": "Combine: \"The teacher arrived.\" + \"The students became silent.\"", "points": 1, "acceptedAnswers": ["As soon as the teacher arrived, the students became silent.", "When the teacher arrived, the students became silent."]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 2: Sentence Combination Practice';

update module_content mc
set data = '{"instructions": "Directions: Choose the option that best completes or corrects each sentence.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "Subject-Verb Agreement: The group of students ___ preparing for the school presentation.", "points": 1, "options": ["are", "were", "is", "have"], "correctIndex": 2}, {"id": "q2", "type": "multiple_choice", "prompt": "Verb Tense: Yesterday, the students ___ their research project to the panel.", "points": 1, "options": ["present", "presented", "presenting", "have presented"], "correctIndex": 1}, {"id": "q3", "type": "multiple_choice", "prompt": "Sentence Structure: Which sentence is grammatically correct?", "points": 1, "options": ["The students finished their assignment they submitted it on time.", "The students finished their assignment, and they submitted it on time.", "The students finishing their assignment, they submitted on time.", "The students their assignment finished and submitted it on time."], "correctIndex": 1}, {"id": "q4", "type": "multiple_choice", "prompt": "Correct Use of Modifiers: Which sentence has the clearest, most appropriate placement of the modifier?", "points": 1, "options": ["The teacher explained carefully the difficult lesson to the students.", "The teacher carefully explained the difficult lesson to the students.", "The teacher explained the difficult carefully lesson to the students.", "Carefully the teacher explained to the students the difficult lesson."], "correctIndex": 1}, {"id": "q5", "type": "multiple_choice", "prompt": "Sentence Combination: \"The students studied diligently. They wanted to achieve high grades.\" Which sentence best combines the two ideas?", "points": 1, "options": ["The students studied diligently, because achieving high grades.", "The students studied diligently they wanted to achieve high grades.", "The students studied diligently because they wanted to achieve high grades.", "The students because wanted to achieve high grades studied diligently."], "correctIndex": 2}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Activity 3: Practicing Syntactic Competence';

update module_content mc
set data = '{"instructions": "Directions: Read each question carefully and choose the best answer.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "What is the correct formal version of this sentence: \"We had so many quizzes, super stress me.\"?", "points": 1, "options": ["We had lots of quizzes, so it was fun.", "We had many quizzes, and I was very stressed.", "There were lots of quizzes, and everyone passed.", "I did well despite the many quizzes."], "correctIndex": 1}, {"id": "q2", "type": "multiple_choice", "prompt": "Which word correctly completes this sentence: \"Our group has already ___ the report.\"", "points": 1, "options": ["submit", "submitting", "submitted", "submission"], "correctIndex": 2}, {"id": "q3", "type": "multiple_choice", "prompt": "Which of the following is a correct example of morphological competence?", "points": 1, "options": ["Misusing punctuation in a sentence", "Saying \"He goed to school\"", "Using \"re-enroll\" to mean enroll again", "Forgetting to capitalize a proper noun"], "correctIndex": 2}, {"id": "q4", "type": "multiple_choice", "prompt": "Which sentence uses proper academic syntax?", "points": 1, "options": ["I text u later if I get news.", "I will send you a message if I receive an update.", "Will send you update later.", "Maybe I text later when have info."], "correctIndex": 1}, {"id": "q5", "type": "multiple_choice", "prompt": "What is the best definition for the word \"tuition\"?", "points": 1, "options": ["A university building", "A type of assignment", "A payment for education", "A classroom activity"], "correctIndex": 2}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 1: Linguistic Competence'
  and mc.title = 'Self-Check & Reflection';

update module_content mc
set data = '{"instructions": "Directions: Recast each informal sentence into a more context-appropriate expression.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "Recast: \u201cWhat time are you coming?\u201d", "points": 1, "acceptedAnswers": ["What time will you arrive?", "What time will you be arriving?"]}, {"id": "q2", "type": "short_answer", "prompt": "Recast: \u201cI\u2019m late. Wait a sec.\u201d", "points": 1, "acceptedAnswers": ["I apologize, I will be there shortly.", "I apologize for being late; please wait a moment."]}, {"id": "q3", "type": "short_answer", "prompt": "Recast: \u201cI don\u2019t know anything about that.\u201d", "points": 1, "acceptedAnswers": ["I''m not familiar with that topic.", "I\u2019m not familiar with that topic.", "I\u2019m not familiar with that, unfortunately."]}, {"id": "q4", "type": "short_answer", "prompt": "Recast: \u201cWhy didn\u2019t he come?\u201d", "points": 1, "acceptedAnswers": ["Do you know why he was absent?", "May I ask why he was unable to attend?"]}, {"id": "q5", "type": "short_answer", "prompt": "Recast: \u201cMan, the test was so hard!\u201d", "points": 1, "acceptedAnswers": ["The test was quite challenging.", "The examination was quite challenging."]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 2: Sociolinguistic Competence'
  and mc.title = 'Activity 1: Expression Recasting';

update module_content mc
set data = '{"instructions": "Directions: Write both a formal and an informal version of each situation below. Answers may vary — your teacher will read and score these.", "questions": [{"id": "q1f", "type": "short_answer", "subjective": true, "prompt": "**Formal:** Inviting a classmate to group work", "points": 1, "sampleAnswer": "Would you like to join our group for this activity?"}, {"id": "q1i", "type": "short_answer", "subjective": true, "prompt": "**Informal:** Inviting a classmate to group work", "points": 1, "sampleAnswer": "Hey, wanna join our group?"}, {"id": "q2f", "type": "short_answer", "subjective": true, "prompt": "**Formal:** Asking a teacher to extend a deadline", "points": 1, "sampleAnswer": "Would it be possible to request a short extension for the deadline?"}, {"id": "q2i", "type": "short_answer", "subjective": true, "prompt": "**Informal:** Asking a teacher to extend a deadline", "points": 1, "sampleAnswer": "Can I have a bit more time to pass this?"}, {"id": "q3f", "type": "short_answer", "subjective": true, "prompt": "**Formal:** Apologizing for being late", "points": 1, "sampleAnswer": "I apologize for arriving late."}, {"id": "q3i", "type": "short_answer", "subjective": true, "prompt": "**Informal:** Apologizing for being late", "points": 1, "sampleAnswer": "Sorry, I''m late!"}, {"id": "q4f", "type": "short_answer", "subjective": true, "prompt": "**Formal:** Congratulating a classmate", "points": 1, "sampleAnswer": "Congratulations on your achievement."}, {"id": "q4i", "type": "short_answer", "subjective": true, "prompt": "**Informal:** Congratulating a classmate", "points": 1, "sampleAnswer": "Nice job, congrats!"}, {"id": "q5f", "type": "short_answer", "subjective": true, "prompt": "**Formal:** Giving feedback on a peer''s work", "points": 1, "sampleAnswer": "Your work was well done overall, though a few areas could be improved."}, {"id": "q5i", "type": "short_answer", "subjective": true, "prompt": "**Informal:** Giving feedback on a peer''s work", "points": 1, "sampleAnswer": "Pretty good, but you could tweak a few parts."}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 2: Sociolinguistic Competence'
  and mc.title = 'Activity 2: Writing Formal and Informal Expressions';

update module_content mc
set data = '{"instructions": "Directions: Match the linguistic realization to the appropriate situation.", "questions": [{"id": "q1", "type": "matching", "prompt": "Match each situation to the appropriate expression.", "points": 5, "pairs": [{"left": "Asking a friend casually", "right": "\u201cBro, do you need help?\u201d"}, {"left": "Talking to a dean formally", "right": "\u201cGood evening, Dean. May I request a short appointment?\u201d"}, {"left": "Making an excuse to a teacher", "right": "\u201cMiss, I wasn\u2019t able to submit it earlier due to an emergency.\u201d"}, {"left": "Casual plan with a peer", "right": "\u201cDude, let\u2019s grab snacks!\u201d"}, {"left": "Clarifying something with a teacher", "right": "\u201cSir, may I clarify something about the lecture?\u201d"}]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 2: Sociolinguistic Competence'
  and mc.title = 'Activity 3: Context Matching';

update module_content mc
set data = '{"instructions": "Directions: Read each statement and decide whether it is appropriate or inappropriate for the given situation. If it is inappropriate, rewrite it using a more context-appropriate form, considering formality, politeness, vocabulary, and the relationship between the speakers. Your teacher will read and score your revisions.", "questions": [{"id": "q1", "type": "short_answer", "subjective": true, "prompt": "Situation: You are speaking to your professor after class. \"Hey, can you explain this part again?\"", "points": 1, "sampleAnswer": "Inappropriate. Revised: \"Professor, could you please explain this part again?\""}, {"id": "q2", "type": "short_answer", "subjective": true, "prompt": "Situation: You are messaging your close classmate about a group project. \"Good afternoon. I would like to inquire whether you have completed your assigned portion.\"", "points": 1, "sampleAnswer": "Inappropriate (too formal). Revised: \"Hi! Have you finished your part of the group project?\""}, {"id": "q3", "type": "short_answer", "subjective": true, "prompt": "Situation: You are requesting an extension from your teacher. \"Can you give me more time? I wasn''t able to finish it.\"", "points": 1, "sampleAnswer": "Inappropriate. Revised: \"Ma''am/Sir, may I kindly request an extension for the submission? I was unable to complete the task on time.\""}, {"id": "q4", "type": "short_answer", "subjective": true, "prompt": "Situation: You are talking to your close friend about an upcoming examination. \"I would like to inform you that I am concerned about the difficulty of the examination.\"", "points": 1, "sampleAnswer": "Inappropriate (too formal). Revised: \"I''m kind of worried. The exam might be really difficult.\""}, {"id": "q5", "type": "short_answer", "subjective": true, "prompt": "Situation: You are giving feedback to a classmate about a presentation. \"Your presentation was okay, but you need to do better next time.\"", "points": 1, "sampleAnswer": "Inappropriate (too blunt). Revised: \"Your presentation was good overall. You could improve the organization of your ideas and speak a little more clearly next time.\""}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 2: Sociolinguistic Competence'
  and mc.title = 'Activity 4: Contextual Expression Revision';

update module_content mc
set data = '{"instructions": "Directions: Choose the more polite response for each situation.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "A teacher corrects you. Do you say:", "points": 1, "options": ["\u201cOkay, noted.\u201d", "\u201cThank you for the correction, Ma\u2019am.\u201d"], "correctIndex": 1}, {"id": "q2", "type": "multiple_choice", "prompt": "You bump into someone in the hallway. Do you say:", "points": 1, "options": ["\u201cSorry, excuse me.\u201d", "\u201cWatch it.\u201d"], "correctIndex": 0}, {"id": "q3", "type": "multiple_choice", "prompt": "You\u2019re late to class. Do you say:", "points": 1, "options": ["\u201cSorry po for being late.\u201d", "\u201cI\u2019m here now, let\u2019s begin.\u201d"], "correctIndex": 0}, {"id": "q4", "type": "multiple_choice", "prompt": "You didn\u2019t understand a lecture. Do you say:", "points": 1, "options": ["\u201cWhat are you talking about?\u201d", "\u201cI didn\u2019t quite catch that. May I ask again?\u201d"], "correctIndex": 1}, {"id": "q5", "type": "multiple_choice", "prompt": "You\u2019re asking for an extension. Do you say:", "points": 1, "options": ["\u201cCan you move the deadline?\u201d", "\u201cMay I respectfully request for an extension?\u201d"], "correctIndex": 1}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 2: Sociolinguistic Competence'
  and mc.title = 'Activity 5: Using Appropriate Polite Expression';

update module_content mc
set data = '{"instructions": "Directions: Choose one of the situations below and create a short dialogue of 5\u20136 lines. Use language appropriate to the social context and relationship between the speakers, including tone, politeness, formality, and cultural sensitivity.\n\nChoose one situation:\nA. A student and a dean during a consultation\nB. Two classmates collaborating on a project", "questions": [{"id": "q1", "type": "short_answer", "subjective": true, "prompt": "Write your dialogue (5\u20136 lines) for your chosen situation.", "points": 5, "sampleAnswer": "Student: Good afternoon, Dean. May I request a short consultation? Dean: Of course, please come in. Student: Thank you. I wanted to ask about my course load for next semester. Dean: Sure, let''s go over your options together. Student: I really appreciate your time and guidance, Dean. Dean: You''re welcome; feel free to reach out anytime."}]}'::jsonb
from modules m
where m.id = mc.module_id
