update module_content mc
set data = '{"instructions": "Directions: Read each question carefully and choose the best answer.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "Which of the following sentences shows appropriate linguistic realization in a formal setting?", "points": 1, "options": ["\u201cHey Prof, I didn\u2019t get the lesson.\u201d", "\u201cMa\u2019am, can you repeat that part again?\u201d", "\u201cExcuse me, Ma\u2019am. May I ask a clarification regarding the topic?\u201d", "\u201cWhat did you say again, Ma\u2019am?\u201d"], "correctIndex": 2}, {"id": "q2", "type": "multiple_choice", "prompt": "Choose the better expression when making an academic apology:", "points": 1, "options": ["\u201cSorry, I just woke up.\u201d", "\u201cI apologize for being late due to personal reasons.\u201d", "\u201cBetter chill, Ma\u2019am.\u201d", "\u201cI got stuck in traffic, hence, I\u2019m late.\u201d"], "correctIndex": 1}, {"id": "q3", "type": "multiple_choice", "prompt": "Which expression would be most appropriate when speaking to a dean?", "points": 1, "options": ["\u201cDean, I need help.\u201d", "\u201cHi Sir, can I ask a question?\u201d", "\u201cGood afternoon, Dean. May I request for a short consultation?\u201d", "\u201cSir, let\u2019s talk.\u201d"], "correctIndex": 2}, {"id": "q4", "type": "multiple_choice", "prompt": "In informal situations, which of the following is acceptable?", "points": 1, "options": ["\u201cCan I respectfully ask a favor, bro?\u201d", "\u201cHey dude, let\u2019s grab lunch!\u201d", "\u201cI humbly request your presence, bestie.\u201d", "\u201cGood evening, please allow me to join you.\u201d"], "correctIndex": 1}, {"id": "q5", "type": "multiple_choice", "prompt": "What is linguistic realization mainly concerned with?", "points": 1, "options": ["Forming complete sentences", "Choosing the correct spelling of words", "Using language appropriate to the context", "Speaking fluently without pauses"], "correctIndex": 2}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 2: Sociolinguistic Competence'
  and mc.title = 'Self-Check & Reflection';

update module_content mc
set data = '{"instructions": "Directions: Read each paragraph and identify the best topic sentence.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "Paragraph 1: Studying in college can be challenging for many students, but time management is crucial for academic success. One way to manage your time effectively is by setting aside specific blocks of time for studying each day. It''s also helpful to avoid distractions, such as turning off your phone while studying. Balancing schoolwork with other commitments can help ensure you stay on top of your studies.", "points": 1, "options": ["College students must develop good time management skills.", "Time management helps balance schoolwork and personal life.", "College life is challenging without effective time management.", "Effective time management can lead to academic success."], "correctIndex": 3}, {"id": "q2", "type": "multiple_choice", "prompt": "Paragraph 2: Many students prefer to study at night when fewer people are around, and the campus is quieter. This can provide a peaceful environment where students can concentrate better. Additionally, for night owls, studying at night aligns with their natural productivity rhythms. On the other hand, others prefer morning study sessions when they feel more refreshed.", "points": 1, "options": ["Students tend to study at night to avoid distractions.", "Quiet study environments are preferred by many students.", "Studying at night can be more effective for some students.", "Night study sessions are preferred by some students for better concentration."], "correctIndex": 2}, {"id": "q3", "type": "multiple_choice", "prompt": "Paragraph 3: Group projects in college are a great way for students to enhance their communication and collaboration skills. Working with peers allows students to share ideas, brainstorm solutions, and develop a deeper understanding of the subject matter. Additionally, group projects help students learn how to delegate tasks and manage deadlines. However, teamwork also requires patience and flexibility to ensure that everyone''s ideas are considered.", "points": 1, "options": ["Group projects enhance communication and teamwork skills.", "Students often struggle with collaboration during group projects.", "Working in groups is essential for academic success.", "Group projects help students improve collaboration and responsibility."], "correctIndex": 0}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 3: Discourse Competence'
  and mc.title = 'Activity 1: Topic Sentence Identification';

update module_content mc
set data = '{"instructions": "Directions: Rearrange the sentences into a coherent paragraph. Choose the option with the correct order.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "Item 1 — a. Finally, we presented our work confidently. b. We brainstormed ideas and selected the best one. c. The group project was a success. d. Everyone contributed during the research phase.", "points": 1, "options": ["c, b, d, a", "b, d, c, a", "d, b, a, c", "a, c, b, d"], "correctIndex": 0}, {"id": "q2", "type": "multiple_choice", "prompt": "Item 2 — a. I checked my backpack to make sure I had everything. b. I quickly got dressed and brushed my teeth. c. When the alarm rang, I jumped out of bed. d. Then I left for school.", "points": 1, "options": ["c, b, a, d", "c, b, d, a", "d, b, c, a", "a, c, b, d"], "correctIndex": 0}, {"id": "q3", "type": "multiple_choice", "prompt": "Item 3 — a. We all clapped and cheered as she crossed the finish line. b. Our classmate joined a local marathon last weekend. c. She trained for weeks to build her stamina. d. During the race, she kept a steady pace and didn''t give up.", "points": 1, "options": ["a, b, c, d", "c, b, d, a", "b, c, d, a", "b, d, c, a"], "correctIndex": 2}, {"id": "q4", "type": "multiple_choice", "prompt": "Item 4 — a. He turned off the lights and closed the door. b. After dinner, my dad washed the dishes. c. Then he watered the plants in the garden. d. When everything was done, he got ready for bed.", "points": 1, "options": ["c, b, a, d", "a, b, c, d", "d, c, b, a", "b, c, a, d"], "correctIndex": 3}, {"id": "q5", "type": "multiple_choice", "prompt": "Item 5 — a. Suddenly, it started to rain heavily. b. I grabbed my umbrella and ran to the bus stop. c. I was walking to school on a cloudy morning. d. I arrived just in time, soaking wet but safe.", "points": 1, "options": ["b, a, c, d", "c, a, b, d", "a, c, b, d", "c, b, a, d"], "correctIndex": 1}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 3: Discourse Competence'
  and mc.title = 'Activity 2: Sequencing Exercise';

update module_content mc
set data = '{"instructions": "Directions: For each set, decide whether the sentence supports the given main idea. Mark True if it belongs, False if it does not.", "questions": [{"id": "q1", "type": "true_false", "prompt": "Main Idea: Watching movies — \"I enjoy watching movies.\"", "points": 1, "correctAnswer": true}, {"id": "q2", "type": "true_false", "prompt": "Main Idea: Watching movies — \"My favorite genres are comedy and action.\"", "points": 1, "correctAnswer": true}, {"id": "q3", "type": "true_false", "prompt": "Main Idea: Watching movies — \"Bananas are high in potassium.\"", "points": 1, "correctAnswer": false}, {"id": "q4", "type": "true_false", "prompt": "Main Idea: Using the internet for learning — \"The internet provides access to unlimited information.\"", "points": 1, "correctAnswer": true}, {"id": "q5", "type": "true_false", "prompt": "Main Idea: Using the internet for learning — \"Many students use it for research and school projects.\"", "points": 1, "correctAnswer": true}, {"id": "q6", "type": "true_false", "prompt": "Main Idea: Using the internet for learning — \"Reading books can improve vocabulary.\"", "points": 1, "correctAnswer": false}, {"id": "q7", "type": "true_false", "prompt": "Main Idea: Physical benefits of basketball — \"Basketball helps improve physical fitness.\"", "points": 1, "correctAnswer": true}, {"id": "q8", "type": "true_false", "prompt": "Main Idea: Physical benefits of basketball — \"Playing regularly builds endurance and coordination.\"", "points": 1, "correctAnswer": true}, {"id": "q9", "type": "true_false", "prompt": "Main Idea: Physical benefits of basketball — \"Math is my least favorite subject in school.\"", "points": 1, "correctAnswer": false}, {"id": "q10", "type": "true_false", "prompt": "Main Idea: Family birthday traditions — \"My family always celebrates birthdays with a special dinner.\"", "points": 1, "correctAnswer": true}, {"id": "q11", "type": "true_false", "prompt": "Main Idea: Family birthday traditions — \"We cook our favorite meals and invite close friends.\"", "points": 1, "correctAnswer": true}, {"id": "q12", "type": "true_false", "prompt": "Main Idea: Family birthday traditions — \"Mount Everest is the highest mountain in the world.\"", "points": 1, "correctAnswer": false}, {"id": "q13", "type": "true_false", "prompt": "Main Idea: Learning English — \"Learning English takes time and practice.\"", "points": 1, "correctAnswer": true}, {"id": "q14", "type": "true_false", "prompt": "Main Idea: Learning English — \"Speaking with native speakers helps improve fluency.\"", "points": 1, "correctAnswer": true}, {"id": "q15", "type": "true_false", "prompt": "Main Idea: Learning English — \"The Great Wall of China is a popular tourist attraction.\"", "points": 1, "correctAnswer": false}]}'::jsonb
