update module_content mc
set data = '{"instructions": "Directions: Choose the most appropriate cohesive device to complete each sentence.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "I studied hard for the test; __________, I got a high score.", "points": 1, "acceptedAnswers": ["therefore", "as a result", "consequently"]}, {"id": "q2", "type": "short_answer", "prompt": "The weather was bad; __________, we postponed the event.", "points": 1, "acceptedAnswers": ["as a result", "therefore", "so"]}, {"id": "q3", "type": "short_answer", "prompt": "I enjoy writing; __________, I''m not fond of reading.", "points": 1, "acceptedAnswers": ["however", "but"]}, {"id": "q4", "type": "short_answer", "prompt": "She is good at singing. __________, she can also play the guitar.", "points": 1, "acceptedAnswers": ["in addition", "moreover", "furthermore", "additionally"]}, {"id": "q5", "type": "short_answer", "prompt": "The lecture was long. __________, it was very informative.", "points": 1, "acceptedAnswers": ["nevertheless", "however", "still"]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 3: Discourse Competence'
  and mc.title = 'Activity 1: Using Appropriate Cohesive Device';

update module_content mc
set data = '{"instructions": "Directions: Combine the following sentences into one using an appropriate cohesive device.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "The project was challenging. We completed it successfully.", "points": 1, "acceptedAnswers": ["The project was challenging; however, we completed it successfully.", "The project was challenging, but we completed it successfully."]}, {"id": "q2", "type": "short_answer", "prompt": "She was tired. She continued working.", "points": 1, "acceptedAnswers": ["She was tired; nevertheless, she continued working.", "Although she was tired, she continued working."]}, {"id": "q3", "type": "short_answer", "prompt": "It rained heavily. The game was canceled.", "points": 1, "acceptedAnswers": ["It rained heavily; therefore, the game was canceled.", "It rained heavily, so the game was canceled."]}, {"id": "q4", "type": "short_answer", "prompt": "He didn''t study for the test. He failed.", "points": 1, "acceptedAnswers": ["He didn''t study for the test, so he failed."]}, {"id": "q5", "type": "short_answer", "prompt": "I woke up late. I missed the bus.", "points": 1, "acceptedAnswers": ["I woke up late; as a result, I missed the bus.", "I woke up late, so I missed the bus."]}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 3: Discourse Competence'
  and mc.title = 'Activity 2: Sentence Linking';

update module_content mc
set data = '{"instructions": "Directions: Reconstruct the scrambled sentences into a cohesive paragraph. Use cohesive devices to connect them.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "Set 1 — a. We assigned roles based on each member''s strength. b. We were given a week to finish our final project. c. Everyone gave their best effort. d. As a result, we completed the task on time.", "points": 2, "acceptedAnswers": ["We were given a week to finish our final project. We assigned roles based on each member''s strength. Everyone gave their best effort. As a result, we completed the task on time."]}, {"id": "q2", "type": "short_answer", "prompt": "Set 2 — a. We reviewed the presentation several times. b. Our group was assigned to present the topic in class. c. We corrected the parts that needed improvement. d. Therefore, we were able to deliver the presentation confidently.", "points": 2, "acceptedAnswers": ["Our group was assigned to present the topic in class. We reviewed the presentation several times. We corrected the parts that needed improvement. Therefore, we were able to deliver the presentation confidently."]}, {"id": "q3", "type": "short_answer", "prompt": "Set 3 — a. She practiced speaking English with her classmates. b. She became more confident in expressing her ideas. c. She initially felt nervous when speaking in front of the class. d. As a result, she participated more actively in class discussions.", "points": 2, "acceptedAnswers": ["She initially felt nervous when speaking in front of the class. She practiced speaking English with her classmates. She became more confident in expressing her ideas. As a result, she participated more actively in class discussions."]}]}'::jsonb
