update module_content mc
set data = '{"instructions": "Directions: Complete the conversation using approximation, then write your own 4-turn dialogue using the same strategy.\n\nStudent A: \"Do you have that thing for slicing paper?\"\nStudent B: \"You mean the __________?\"\nStudent A: \"Yes, the sharp tool with handles.\"\nStudent B: \"Oh, you mean the __________. Here it is.\"", "questions": [{"id": "q1", "type": "short_answer", "prompt": "Fill in both blanks (they are the same word).", "points": 1, "acceptedAnswers": ["scissors"]}, {"id": "q2", "type": "short_answer", "subjective": true, "prompt": "Task: Write a 4-turn dialogue in which you ask about an object that you cannot name directly. Use approximation to describe the object.", "points": 3, "sampleAnswer": "Student A: \"Can you hand me the thing we use to hold papers together?\" Student B: \"You mean the little metal clip?\" Student A: \"Yes, the small clip you press to open.\" Student B: \"Oh, you mean the paper clip. Here it is.\""}]}'::jsonb
