update module_content mc
set data = '{"instructions": "Directions: Rephrase the following broken or unclear sentences.", "questions": [{"id": "q1", "type": "short_answer", "prompt": "\"Him absent again today.\"", "points": 1, "acceptedAnswers": ["He is absent again today."]}, {"id": "q2", "type": "short_answer", "prompt": "\"No understand topic.\"", "points": 1, "acceptedAnswers": ["I didn''t understand the topic.", "I don''t understand the topic."]}, {"id": "q3", "type": "short_answer", "prompt": "\"Project late submit.\"", "points": 1, "acceptedAnswers": ["The project was submitted late."]}, {"id": "q4", "type": "short_answer", "prompt": "\"Test hard, not review.\"", "points": 1, "acceptedAnswers": ["The test was difficult because I didn''t review.", "The test was hard because I didn''t review."]}, {"id": "q5", "type": "short_answer", "prompt": "\"I busy, later talk.\"", "points": 1, "acceptedAnswers": ["I''m busy right now. Let''s talk later.", "I''m busy right now; let''s talk later."]}]}'::jsonb
