update module_content mc
set data = '{"instructions": "Directions: Below is a series of broken or informal chat messages. Choose the best revised version from the options provided.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "Original: \"U submit? Not yet why? Prof say submit now.\"", "points": 1, "options": ["You submit already? Why no? The prof want now.", "Have you submitted? Not yet? The professor said we should submit now.", "Submit done? Why late? Teacher ask now.", "Prof say submit, u submit not yet why?"], "correctIndex": 1}, {"id": "q2", "type": "multiple_choice", "prompt": "Original: \"Me no idea what to do. U done?\"", "points": 1, "options": ["I don''t know what doing. You finished?", "Me confused. Are you doing?", "I have no idea what to do. Have you finished?", "No clue what to do, did you?"], "correctIndex": 2}, {"id": "q3", "type": "multiple_choice", "prompt": "Original: \"Cant join meet. Net bad. Tell sir pls.\"", "points": 1, "options": ["I can''t join the meeting. My internet is bad. Please tell sir.", "Can''t join, net no good. Inform.", "Net bad join no. Tell teacher.", "Meeting no go. You tell?"], "correctIndex": 0}, {"id": "q4", "type": "multiple_choice", "prompt": "Original: \"Where link? U got it? Mine gone.\"", "points": 1, "options": ["Got link? My gone. Share please.", "Where is the link? Do you have it? I lost mine.", "U have the link, I no.", "Link? Mine deleted. Yours?"], "correctIndex": 1}, {"id": "q5", "type": "multiple_choice", "prompt": "Original: \"Late again. She mad?\"", "points": 1, "options": ["I''m late again. Is she angry?", "Again late. She angry?", "She mad I late?", "Late again. She scold?"], "correctIndex": 0}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 4: Strategic Competence'
  and mc.title = 'Activity 2: Chat Message Repair';

update module_content mc
set data = '{"instructions": "Directions: Read each unclear or incomplete message. Rewrite it to make the meaning clear, complete, and appropriate for communication. You may add or rearrange words, but keep the original meaning. Answers may vary — your teacher will read and score them. Example — Original: \"Meeting tomorrow? What time again?\" Reconstructed: \"What time is our meeting tomorrow?\"", "questions": [{"id": "q1", "type": "short_answer", "subjective": true, "prompt": "\"Need submit project today but printer no work.\"", "points": 1, "sampleAnswer": "I need to submit my project today, but the printer isn''t working."}, {"id": "q2", "type": "short_answer", "subjective": true, "prompt": "\"Can you send file? I cannot find mine.\"", "points": 1, "sampleAnswer": "Can you send me the file? I can''t find mine."}, {"id": "q3", "type": "short_answer", "subjective": true, "prompt": "\"Teacher said change it but I don''t know what part.\"", "points": 1, "sampleAnswer": "The teacher said to change it, but I don''t know which part."}, {"id": "q4", "type": "short_answer", "subjective": true, "prompt": "\"Sorry late reply. I was busy earlier.\"", "points": 1, "sampleAnswer": "Sorry for the late reply. I was busy earlier."}, {"id": "q5", "type": "short_answer", "subjective": true, "prompt": "\"Group meeting where? Library or classroom?\"", "points": 1, "sampleAnswer": "Where is the group meeting, the library or the classroom?"}, {"id": "q6", "type": "short_answer", "subjective": true, "prompt": "**Challenge:** Choose one of the reconstructed messages above and rewrite it as if you were sending it to a teacher or professor. Pay attention to clarity, politeness, and formality.", "points": 2, "sampleAnswer": "Good day, Sir/Ma''am. I would like to inform you that I need to submit my project today, but my printer is currently not working. I apologize for the inconvenience and will find another way to print it as soon as possible."}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 4: Strategic Competence'
  and mc.title = 'Activity 3: Fix the Message';

