  and mc.title = 'Activity 4: Listening and Message Reconstruction';

update module_content mc
set data = '{"instructions": "Directions: Read each question carefully and choose the best answer.", "questions": [{"id": "q1", "type": "multiple_choice", "prompt": "What is approximation in strategic competence?", "points": 1, "options": ["Using exact words all the time", "Describing things without naming them directly", "Avoiding conversation", "Memorizing vocabulary lists"], "correctIndex": 1}, {"id": "q2", "type": "multiple_choice", "prompt": "What should you do when you forget a word in English?", "points": 1, "options": ["Stop talking", "Say nothing", "Use a near-equivalent word", "Say \"I don''t know\" only"], "correctIndex": 2}, {"id": "q3", "type": "multiple_choice", "prompt": "Reconstruction is useful when:", "points": 1, "options": ["You want to memorize a speech", "You are taking a reading test", "You have to rephrase a confusing statement", "You don''t want to talk"], "correctIndex": 2}, {"id": "q4", "type": "multiple_choice", "prompt": "Which sentence shows correct reconstruction?", "points": 1, "options": ["\"No review, hard test.\"", "\"I didn''t review, so the test was hard.\"", "\"Review test no me.\"", "\"Test okay, but me not study.\""], "correctIndex": 1}, {"id": "q5", "type": "multiple_choice", "prompt": "Which shows strategic competence?", "points": 1, "options": ["Using gestures to support speech", "Writing poetry only", "Memorizing grammar rules", "Reading silently"], "correctIndex": 0}]}'::jsonb
from modules m
where m.id = mc.module_id
  and m.title = 'Module 4: Strategic Competence'
  and mc.title = 'Self-Check & Reflection';


